param([string]$ProjectRoot=(Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference='Stop'
function ReadL([string]$p){@(Get-Content (Join-Path $ProjectRoot $p)|Where-Object{$_}|ForEach-Object{$_|ConvertFrom-Json})}
function Key([string]$s){$k=($s.ToLowerInvariant()-replace '[^a-z0-9]+',' ' -replace '\s+',' ').Trim();$k=$k-replace '\s+(?:class|type)\s+(?:i{1,3}|iv|v|[1-5])$','';$k=$k-replace '\s+(?:gold|silver|bronze)$','';$map=@{'cordon of honour'='collar of honour';'order of loyal son of sudan'='order of the loyal son of sudan';'order of persistance'='order of persistence';'duty medal'='medal of duty';'army distinguished service medal'='army distinguished service medal';'defence force long service and good conduct medal'='sudan defence force long service and good conduct medal'};if($map.ContainsKey($k)){$k=$map[$k]};$k}
function Slug([string]$s){(($s.ToUpperInvariant()-replace '[^A-Z0-9]+','-').Trim('-'))}
$base=ReadL 'data/raw_candidates/wawards_medalsorg_sudan.jsonl';$mb=ReadL 'data/raw_candidates/medalbook_sudan.jsonl'
$all=[Collections.Generic.List[object]]::new();foreach($r in $base){$all.Add([pscustomobject]@{key=(Key $r.page_title);row=$r})};foreach($r in $mb){$name=if($r.family_hint){$r.family_hint}else{$r.page_title};$all.Add([pscustomobject]@{key=(Key $name);row=$r})}
$families=[Collections.Generic.List[object]]::new();$conflicts=[Collections.Generic.List[object]]::new()
foreach($g in $all|Group-Object key){$rows=@($g.Group.row);$systems=@($rows.source_system|Sort-Object -Unique);$dates=@($rows.date_candidates|ForEach-Object{$_}|Where-Object{$_ -notin @(2007,2026)}|Sort-Object -Unique);$variants=@($rows|ForEach-Object{[ordered]@{title=$_.page_title;source_system=$_.source_system;page_url=$_.page_url;date_candidates=@($_.date_candidates|Where-Object{$_ -notin @(2007,2026)});image_urls=@($_.original_image_urls);local_raw_images=@($_.local_raw_images)}});$localImages=@($rows.local_raw_images|ForEach-Object{$_}|Where-Object{$_}|Sort-Object -Unique);$family=[ordered]@{scope_id='sudan';family_id='SDN-'+(Slug $g.Name);preferred_name=$rows[0].page_title;aliases=@($rows.page_title|Sort-Object -Unique);date_candidates=$dates;source_systems=$systems;normalization_status=if($systems.Count -gt 1){'cross_source_family_match'}elseif($systems -contains 'MedalBook Sudan catalogue'){'medalbook_single_source_candidate'}else{'directory_single_source_candidate'};variants=$variants;local_raw_images=$localImages;image_review_status=if($localImages.Count){'raw_images_pending_visual_and_rights_review'}else{'missing_image'}};$families.Add($family);if($dates.Count -gt 1){$conflicts.Add([ordered]@{family_id=$family.family_id;type='DATE_CANDIDATES';values=$dates;status='UNRESOLVED'})}}
$summary=[ordered]@{input_rows=$base.Count+$mb.Count;directory_rows=$base.Count;medalbook_rows=$mb.Count;normalized_families=$families.Count;cross_source_families=@($families|Where-Object normalization_status -eq 'cross_source_family_match').Count;single_source_families=@($families|Where-Object normalization_status -ne 'cross_source_family_match').Count;variant_rows=@($families.variants|ForEach-Object{$_}).Count;families_with_raw_images=@($families|Where-Object{$_.local_raw_images.Count}).Count;raw_images=@($families.local_raw_images|ForEach-Object{$_}|Sort-Object -Unique).Count;catalogue_ready_images=0;conflicts=$conflicts.Count;unresolved_source_page_failures=1}
$payload=[ordered]@{schema_version='2.0';as_of='2026-09-26';batch_id='sudan_normalized_batch2';status='normalized_draft_not_html_approved';summary=$summary;families=@($families)}
$out=Join-Path $ProjectRoot 'data\normalized\sudan_normalized_batch2.json';$cf=Join-Path $ProjectRoot 'data\conflicts\sudan_normalization_batch2.json';$cp=Join-Path $ProjectRoot 'data\checkpoints\sudan_normalization_batch2_2026-09-26.json';[IO.File]::WriteAllText($out,($payload|ConvertTo-Json -Depth 15),[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText($cf,([ordered]@{schema_version='2.0';as_of='2026-09-26';conflicts=@($conflicts)}|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText($cp,([ordered]@{schema_version='2.0';as_of='2026-09-26';batch='sudan_normalized_batch2';summary=$summary;next_action='Visually review 77 raw MedalBook images, bind complete object views to cross-source families, and replace commercial-only evidence where an official or Commons source is available.'}|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));$summary|ConvertTo-Json -Depth 6
